-- GENERATED by `wfj generate` from data/gossip/gossip-40.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["4000be6a2f46e178"] = { "Salute, {class}. Sono l'ufficiale degli encomi che agisce per conto di Darnassus. Il mio dovere è assistere gli avventurieri che hanno ricevuto Anelli d'Encomio dell'⟦Alliance=Alleanza⟧.\n\nAccetto anelli in quantità diverse, ma lo scambio più vantaggioso per te è consegnarne un set di dieci in una volta. Quando consegnerai gli anelli, registrerò le tue imprese nei nostri archivi. Di conseguenza, otterrai il riconoscimento di Darnassus per il tuo impegno e il tuo servizio.", "." },
  ["400288a265bea20b"] = { "Mentre mio fratello Drazial concentra le sue analisi sulla natura più fisica delle bestie delle Terre Devastate, io tendo a concentrarmi sugli aspetti più mentali e spirituali della fauna.\n\nÈ vero che le bestie mostrano forza, agilità e tempra estremamente insolite, ma alcune possiedono anche una grande intelligenza e capacità rigenerative slegate dal loro essere fisico.\n\nForse ti interesserebbe aiutarmi a far progredire le mie ricerche, {race}?", "." },
  ["40053c3efe322626"] = { "Se la rivuoi indietro dovrai implorare!", "." },
  ["4005921e513166be"] = { "Che gli spiriti ti proteggano, amico.", "." },
  ["401694ac603ac8e4"] = { "Vediamoci giù al frutteto: devo solo mettere via il fucile.", "." },
  ["40174fc61ea69b1c"] = { "Se devi sistemare il tuo famiglio mentre ne addestri un altro, dovresti parlare con Jenova Stoneshield, laggiù nel Dwarven District.", "." },
  ["401894ac4206848d"] = { "Devi cercare il fabbro Argus. Di solito sorveglia la forgia di ⟦Goldshire=Borgodoro⟧, se ti serve un addestramento.", "." },
  ["402213ef32732bb4"] = { "%s esplode e libera diverse Fanghiglie di Bile!", "." },
  ["4022153c3b442371"] = { "Qualcosa mi dice che anche {name} vuole il fossile misterioso. Aiuto!", "." },
  ["4023e50656d26e1d"] = { "Impugni la lama di mio padre, {name}. I miei soldati sono ai tuoi ordini, <mio/mia> <signore/signora>. Prendili... Guidali... Gli impuri devono essere epurati. Devono essere mondati dalla loro corruzione.", "." },
  ["40331f17ae98f7ae"] = { "No, io no, ma molti altri cercano l'amore. Dovresti comprare i miei pegni d'amore, metterti un po' di colonia o di profumo e poi distribuirli in giro!", "." },
  ["4039189e338975dc"] = { "Mi duole dover combattere {name}.", "." },
  ["4043beab63369b8a"] = { "La Shattered Hand riporterà l'⟦Horde=Orda⟧ alla sua antica gloria, senza farsi frenare dalla timidezza del Capoguerra.", "." },
  ["40468351fdde1838"] = { "Cosa? No, non riparo armature. ⟦Everlook=Lungavista⟧ è circa un miglio più a nord, <fratello/sorella>.\n\nOra compra qualcosa, o sparisci prima che chiami il mio stregone a occuparsi di te!", "." },
  ["405040b0daee1aa7"] = { "Maggiordomo attivato.", "." },
  ["405487abc40c2395"] = { "<Benvenuto/Benvenuta> nella nostra umile dimora! È sempre bello vedere una faccia amica. E che braccia forti che hai. Io e mio marito cerchiamo sempre aiuto alla fattoria. Ora che quasi tutta la brava gente se n'è andata, è difficile trovare qualcuno in grado di dare una mano.", "." },
  ["40576de393172213"] = { "Ignoro l'insulto in modo non troppo discreto, sperando di insinuare nel sovrano il timore di aver commesso una gaffe. Poi, al mio ritorno, riferisco l'insulto al mio signore.", "." },
  ["405e4334c05eb11c"] = { "Bene, cominciamo.", "." },
  ["40605e12ed1cd1d8"] = { "Salve, {name}.", "." },
  ["4061a4eb8dd6db3f"] = { "Riposa ora, figlia mia.", "." },
  ["40641a604c81c1d6"] = { "Bene, sembra tutto in ordine. Mettiamoci in marcia.", "." },
  ["406c4041a414dfb2"] = { "Sì, certo, basta che subito dopo andiamo all'arena!", "." },
  ["406d862eea862968"] = { "%s va su tutte le furie alla vista delle sue truppe cadute.", "." },
  ["406e6c9e02112628"] = { "Ebbene, <ragazzo/ragazza>, pare che l'⟦Alliance=Alleanza⟧ abbia già raccolto tutto ciò che ci serve per la nostra parte della guerra. So che i fabbri, gli ingegneri e tutti gli altri sono impegnati negli ultimi preparativi, e non appena l'⟦Horde=Orda⟧ avrà radunato tutte le sue merci, tutto verrà spedito a ⟦Silithus=Silitus⟧ per la guerra.", "." },
  ["407074caf669a5c5"] = { "Da queste parti l'infestazione dei ⟦Blackrock=Roccianera⟧ è fitta. Farò del mio meglio per tenere il passo, {name}. Andiamo!", "." },
  ["4070b40761ddb906"] = { "Non posso insegnare a un tauren a cavalcare una cavalcatura scheletrica. Mi dispiace, ma non posso fare nulla per te.", "." },
  ["4074d40f0d756bf7"] = { "Mostri una saggezza superiore ai tuoi anni, {class}. Grazie. Troverai la nostra maestra di battaglia, Lylandris, al tavolo di guerra nella Hall of Arms. Può aiutarti a raggiungere la ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", "." },
  ["40762a752ab7e0e6"] = { "Quando ho scavato per uscire dalla tomba, pensavo che la mia famiglia mi avrebbe aperto le braccia. Invece mi hanno fatto scappare dal villaggio, urlando in una lingua che non capivo più.", "." },
  ["407acae453d6af97"] = { "Imparerai, {name}, e un giorno sarai <un/una> grande <cacciatore/cacciatrice>.", "." },
  ["407b0152063f52b2"] = { "Hai davvero una grande determinazione nello studio. Sarà un piacere istruirti!", "." },
  ["407c15c6c4425ea4"] = { "Miranda, potresti dirmi quante insegne costano gli oggetti che offri agli avventurieri con reputazione Onorato?", "." },
  ["4081bb85fef0b13e"] = { "Finito! E i risultati sono straordinari. Devo comunicarli ai miei colleghi Grimand, Mathiel e Klockmort!", "." },
  ["40885e282a2ad431"] = { "Io rappresento la forza che ti sostiene come giovane {class}. Sei qui da me per apprendere questa forza, giovane, e io te la insegnerò. Ti insegnerò tutto ciò che è lo spirito dell'orso, purché tu sappia ascoltare e comprendere.\n\nPer sapere cosa significa attingere al mio spirito, devi comprendere l'importanza della forza del corpo, così come della forza del cuore.", "." },
  ["40963fef0cacc06b"] = { "Il pranzo è servito, miei bellissimi figli. Fateli a pezzi!", "." },
  ["409865ade3d460bd"] = { "Credimi quando te lo dico: rimpiangerai di essere <nato/nata>, femminuccia!", "." },
  ["409958b28a5bf603"] = { "Assicurati che lo legga subito. Temo che il nostro problema con il Flagello sia appena cominciato.\r\n\nTorna da me a tempo debito. Credo di aver quasi scoperto qualcosa per cui mi servirebbe l'aiuto di una lama volenterosa.", "." },
  ["40a187496eac25c8"] = { "Proprio così. Alla fine l'oggetto fu distrutto e Alamorte quasi ucciso dal potere unito e rinnovato dei quattro Aspetti rimasti. Dove si trovi ora Alamorte non si sa. Ciò che sappiamo, però, è che uno dei suoi discendenti, Nefarian, governa questa cittadella e vuole riprendere da dove suo padre si era interrotto.", "." },
  ["40bd5ad932d96f1b"] = { "Dun Baldar ha subito un duro colpo nell'ultimo attacco dell'⟦Horde=Orda⟧! Ci servono altri rifornimenti per ricostruire e fare le riparazioni!", "." },
  ["40bdbb8fe7dc2866"] = { "Via, a ⟦Undercity=Sepulcra⟧, {name}! Cerca di non prenderti la peste...", "." },
  ["40befd091302d915"] = { "Ecco fatto!", "." },
  ["40c3226ca81df904"] = { "È giunto il momento, Davil. È giunto il momento della tua morte!", "." },
  ["40cb0d9bfbb9dd40"] = { "Sei arrivat<o/a> più lontano di molti, {name}. Rispetta gli elementi attorno a te e ti andrà molto meglio che alla maggior parte.", "." },
  ["40cba8f7c44ac6b3"] = { "Si dice che un esercito marci con lo stomaco, ed è la verità. Perché un'offensiva abbia successo, le truppe devono essere ben nutrite e ben rifornite.", "." },
  ["40d92ad5fda8aadd"] = { "Venite, spiriti: servite il vostro padrone!", "." },
  ["40d9e90345ff0507"] = { "Sbalorditivo! Quindi la chiave è l'indurio!", "." },
  ["40dabaa98ee8b9c5"] = { "La cultura va celebrata e condivisa.", "." },
  ["40db37fef6c5353d"] = { "I seguaci della Dama Oscura sono ciechi se credono di poter resistere alla nostra potenza.", "." },
  ["40e08812d761a445"] = { "Tutto qui? Pensavo che volessi sfidarmi.", "." },
  ["40e67aab67730207"] = { "Mamma! Possiamo andare a giocare, ti prego ti prego ti prego? Possiamo, eh? Possiamo?", "." },
  ["40e7c74070a7c3b8"] = { "Brzzzzt!\n\nBenvenuto nel Matrix Punchograph 3005 barra D, un terminale di livello di sicurezza delta.\n\nPer accedere alle funzioni del terminale devi possedere una scheda perforata rossa.\n\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100", "." },
  ["40e9d8dbf46811fa"] = { "Quanto durerà l'invasione?", "." },
  ["40eac4cdc92d6e4c"] = { "Ho sentito qualcosa laggiù.", "." },
  ["40eca9a8dae8a7b5"] = { "Non puoi passare. Non sei della nostra stirpe, né hai lanciato la sfida.", "." },
  ["40f72df5d0c1ece5"] = { "*Whirr* *CLANK*\n\nHo ricevuto istruzioni di accettare pesci rari di alta qualità e di dare in cambio preziosi accessori da pesca di Nat Pagle. Pesce richiesto.\n\n*THUMP* *Buzz*", "." },
  ["40f999522d76ae93"] = { "Arrivare fin qui non è stato facile, lo so. Ma come sarebbe noiosa la vita senza sfide, non credi? Bene, perché ho una sfida per te...", "." },
  ["40fa4edd1145e1aa"] = { "Zando'zan della Shattered Hand. Come può aiutarti Zando'zan? Non può! Non vuole!", "." },
  ["40fa5463a374d00a"] = { "Continuo a non capire.", "." },
})
